CREATE DEFINER=`root`@`localhost` TRIGGER `trg_tb_payment_methods_after_update` AFTER UPDATE ON `tb_payment_methods` FOR EACH ROW BEGIN
    DECLARE v_cambios TEXT;
    SET v_cambios = CONCAT_WS('',
        IF(NOT (OLD.`name` <=> NEW.`name`), CONCAT('[name: ', COALESCE(CAST(OLD.`name` AS CHAR), 'NULL'), ' -> ', COALESCE(CAST(NEW.`name` AS CHAR), 'NULL'), '] '), NULL),
        IF(NOT (OLD.`description` <=> NEW.`description`), CONCAT('[description: ', COALESCE(CAST(OLD.`description` AS CHAR), 'NULL'), ' -> ', COALESCE(CAST(NEW.`description` AS CHAR), 'NULL'), '] '), NULL),
        IF(NOT (OLD.`status` <=> NEW.`status`), CONCAT('[status: ', COALESCE(CAST((OLD.`status` + 0) AS CHAR), 'NULL'), ' -> ', COALESCE(CAST((NEW.`status` + 0) AS CHAR), 'NULL'), '] '), NULL)
    );
    IF v_cambios <> '' THEN
        INSERT INTO tb_logs (table_name, operation, db_user, description, operation_date, operation_status)
        VALUES (
            'tb_payment_methods', 'Update', USER(),
            CONCAT('Registro actualizado en tb_payment_methods. ID=', NEW.`ID`, ' | Cambios: ', v_cambios),
            CURRENT_TIMESTAMP, '1'
        );
    END IF;
END;;

