CREATE DEFINER=`root`@`localhost` TRIGGER `trg_tb_people_after_update` AFTER UPDATE ON `tb_people` FOR EACH ROW BEGIN
    DECLARE v_cambios TEXT;
    SET v_cambios = CONCAT_WS('',
        IF(NOT (OLD.`user_ID` <=> NEW.`user_ID`), CONCAT('[user_ID: ', COALESCE(CAST(OLD.`user_ID` AS CHAR), 'NULL'), ' -> ', COALESCE(CAST(NEW.`user_ID` AS CHAR), 'NULL'), '] '), NULL),
        IF(NOT (OLD.`title` <=> NEW.`title`), '[title: modificado] ', NULL),
        IF(NOT (OLD.`given_names` <=> NEW.`given_names`), '[given_names: modificado] ', NULL),
        IF(NOT (OLD.`family_names` <=> NEW.`family_names`), '[family_names: modificado] ', NULL),
        IF(NOT (OLD.`birth_date` <=> NEW.`birth_date`), '[birth_date: modificado] ', NULL),
        IF(NOT (OLD.`gender_ID` <=> NEW.`gender_ID`), '[gender_ID: modificado] ', NULL),
        IF(NOT (OLD.`phone` <=> NEW.`phone`), '[phone: modificado] ', NULL),
        IF(NOT (OLD.`country_code` <=> NEW.`country_code`), '[country_code: modificado] ', NULL),
        IF(NOT (OLD.`status` <=> NEW.`status`), CONCAT('[status: ', COALESCE(CAST((OLD.`status` + 0) AS CHAR), 'NULL'), ' -> ', COALESCE(CAST((NEW.`status` + 0) AS CHAR), 'NULL'), '] '), NULL)
    );
    IF v_cambios <> '' THEN
        INSERT INTO tb_logs (table_name, operation, db_user, description, operation_date, operation_status)
        VALUES (
            'tb_people', 'Update', USER(),
            CONCAT('Registro actualizado en tb_people. ID=', NEW.`person_ID`, ' | Cambios: ', v_cambios),
            CURRENT_TIMESTAMP, '1'
