CREATE DEFINER=`root`@`localhost` TRIGGER `trg_tbd_return_items_after_update` AFTER UPDATE ON `tbd_return_items` FOR EACH ROW BEGIN
    DECLARE v_cambios TEXT;
    SET v_cambios = CONCAT_WS('',
        IF(NOT (OLD.`return_ID` <=> NEW.`return_ID`), CONCAT('[return_ID: ', COALESCE(CAST(OLD.`return_ID` AS CHAR), 'NULL'), ' -> ', COALESCE(CAST(NEW.`return_ID` AS CHAR), 'NULL'), '] '), NULL),
        IF(NOT (OLD.`order_item_ID` <=> NEW.`order_item_ID`), CONCAT('[order_item_ID: ', COALESCE(CAST(OLD.`order_item_ID` AS CHAR), 'NULL'), ' -> ', COALESCE(CAST(NEW.`order_item_ID` AS CHAR), 'NULL'), '] '), NULL),
        IF(NOT (OLD.`quantity` <=> NEW.`quantity`), CONCAT('[quantity: ', COALESCE(CAST(OLD.`quantity` AS CHAR), 'NULL'), ' -> ', COALESCE(CAST(NEW.`quantity` AS CHAR), 'NULL'), '] '), NULL),
        IF(NOT (OLD.`item_condition` <=> NEW.`item_condition`), CONCAT('[item_condition: ', COALESCE(CAST(OLD.`item_condition` AS CHAR), 'NULL'), ' -> ', COALESCE(CAST(NEW.`item_condition` AS CHAR), 'NULL'), '] '), NULL),
        IF(NOT (OLD.`disposition` <=> NEW.`disposition`), CONCAT('[disposition: ', COALESCE(CAST(OLD.`disposition` AS CHAR), 'NULL'), ' -> ', COALESCE(CAST(NEW.`disposition` AS CHAR), 'NULL'), '] '), NULL),
        IF(NOT (OLD.`approved_refund_amount` <=> NEW.`approved_refund_amount`), CONCAT('[approved_refund_amount: ', COALESCE(CAST(OLD.`approved_refund_amount` AS CHAR), 'NULL'), ' -> ', COALESCE(CAST(NEW.`approved_refund_amount` AS CHAR), 'NULL'), '] '), NULL),
        IF(NOT (OLD.`item_status` <=> NEW.`item_status`), CONCAT('[item_status: ', COALESCE(CAST(OLD.`item_status` AS CHAR), 'NULL'), ' -> ', COALESCE(CAST(NEW.`item_status` AS CHAR), 'NULL'), '] '), NULL)
    );
    IF v_cambios <> '' THEN
        INSERT INTO tb_logs (table_name, operation, db_user, description, operation_date, operation_status)
        VALUES (
            'tbd_return_items', 'Update', USER(),
            CONCAT('Registro actualizado en tbd_return_items. ID=', NEW.`ID`, ' | Cambios: ', v_cambios),
            CURRENT_TIMESTAMP, '1'
        );
    END IF;
END;;

