CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_create_order`(
    IN  p_user_id  INT,
    OUT p_order_id INT UNSIGNED,
    OUT p_total    DECIMAL(12,3)
)
BEGIN
    DECLARE v_cart_id INT UNSIGNED DEFAULT NULL;

    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        RESIGNAL;
    END;

    SELECT ID INTO v_cart_id FROM tb_carts WHERE user_ID = p_user_id LIMIT 1;

    IF v_cart_id IS NULL
       OR NOT EXISTS (SELECT 1 FROM tbd_cart_items WHERE cart_ID = v_cart_id) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'El usuario no tiene un carrito con productos';
    END IF;

    IF EXISTS (SELECT 1 FROM tbd_cart_items ci
               JOIN tb_products p ON p.ID = ci.product_offer_ID
               WHERE ci.cart_ID = v_cart_id
                 AND (p.status = b'0' OR p.current_stock < ci.quantity)) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Hay productos inactivos o sin stock suficiente';
    END IF;

    START TRANSACTION;

    INSERT INTO tb_orders (`key`, user_ID, total_products, total_cost, status_string)
    SELECT CONCAT('ORD-', DATE_FORMAT(NOW(), '%Y%m%d'), '-', UPPER(LEFT(REPLACE(UUID(), '-', ''), 8))),
           p_user_id, SUM(ci.quantity), SUM(ci.quantity * p.current_price), 'Registered'
    FROM tbd_cart_items ci
    JOIN tb_products p ON p.ID = ci.product_offer_ID
    WHERE ci.cart_ID = v_cart_id;
    SET p_order_id = LAST_INSERT_ID();

    INSERT INTO tb_seller_orders (order_ID, seller_ID, subtotal, shipping_cost, fulfillment_status)
    SELECT p_order_id, pr.user_ID, SUM(ci.quantity * p.current_price), 0, 'Pending'
    FROM tbd_cart_items ci
    JOIN tb_products p ON p.ID = ci.product_offer_ID
    JOIN tbd_products_users_providers pr ON pr.product_ID = p.ID AND pr.status = b'1'
    WHERE ci.cart_ID = v_cart_id
    GROUP BY pr.user_ID;

    INSERT INTO tbd_order_items (seller_order_ID, product_offer_ID, product_name, quantity, unit_price)
    SELECT so.ID, p.ID, p.name, ci.quantity, p.current_price
    FROM tbd_cart_items ci
    JOIN tb_products p ON p.ID = ci.product_offer_ID
    JOIN tbd_products_users_providers pr ON pr.product_ID = p.ID AND pr.status = b'1'
    JOIN tb_seller_orders so ON so.order_ID = p_order_id AND so.seller_ID = pr.user_ID
    WHERE ci.cart_ID = v_cart_id;

    UPDATE tb_products p
    JOIN tbd_cart_items ci ON ci.product_offer_ID = p.ID
       SET p.current_stock = p.current_stock - ci.quantity
     WHERE ci.cart_ID = v_cart_id;

    UPDATE tb_cart_status SET status = 'Converted' WHERE cart_ID = v_cart_id;

    COMMIT;

    SELECT total_cost INTO p_total FROM tb_orders WHERE ID = p_order_id;
END ;;

CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_generate_user`(
    IN  p_country   CHAR(2),
    IN  p_min_age   INT,
    IN  p_max_age   INT,
    IN  p_is_active TINYINT,          -- 1 = activo, 0 = dado de baja
    OUT p_user_id   INT UNSIGNED
)
BEGIN
    DECLARE c_signup_window_days INT DEFAULT 730;   -- altas en los últimos 2 años
    DECLARE c_min_signup_age     INT DEFAULT 18;    -- edad mínima al registrarse
    DECLARE c_never_login_rate   DOUBLE DEFAULT 0.10;

    DECLARE v_gender      CHAR(1);
    DECLARE v_birth       DATE;
    DECLARE v_given       VARCHAR(60);
    DECLARE v_family      VARCHAR(60);
    DECLARE v_from        DATETIME;
    DECLARE v_created     DATETIME;
    DECLARE v_baja        DATETIME DEFAULT NULL;
    DECLARE v_login_limit DATETIME;
    DECLARE v_last_login  DATETIME DEFAULT NULL;

    -- 1) Identidad
    SET v_gender = fn_gen_gender();
    SET v_birth  = fn_gen_birth_date(p_min_age, p_max_age);
    SET v_given  = fn_gen_given_name(p_country, v_gender, YEAR(v_birth));
    SET v_family = fn_gen_family_name(p_country);

    -- 2) Fechas coherentes: la cuenta no se crea antes de que la persona cumpla 18
    SET v_from = GREATEST(DATE_SUB(NOW(), INTERVAL c_signup_window_days DAY),
                          CAST(DATE_ADD(v_birth, INTERVAL c_min_signup_age YEAR) AS DATETIME));
    IF v_from > NOW() THEN SET v_from = NOW(); END IF;

    SET v_created     = fn_gen_datetime_between(v_from, NOW());
    SET v_login_limit = NOW();

    IF p_is_active = 0 THEN
        SET v_baja        = fn_gen_datetime_between(v_created, NOW());
        SET v_login_limit = v_baja;                 -- no hay logins después de la baja
    END IF;

    IF RAND() >= c_never_login_rate THEN
        SET v_last_login = fn_gen_datetime_between(v_created, v_login_limit);
    END IF;

    -- 3) Persistencia
    CALL sp_insert_user(
        fn_gen_unique_email(v_given, v_family, p_country),
        fn_gen_unique_nick(v_given, v_family),
        fn_default_password_hash(),
        v_created, v_baja, v_last_login, p_is_active,
        p_user_id
    );

    CALL sp_insert_person(
        p_user_id,
        fn_gen_courtesy_title(p_country, v_gender),
        v_given, v_family, v_birth, v_gender, p_country,
        fn_gen_phone(p_country),
        p_is_active, v_created, COALESCE(v_baja, v_created)
    );
END ;;

CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_generate_users_bulk`(
    IN p_total      INT UNSIGNED,
    IN p_country    CHAR(2),
    IN p_min_age    INT,
    IN p_max_age    INT,
    IN p_active_pct DECIMAL(5,2)
)
BEGIN
    DECLARE v_left        INT UNSIGNED;
    DECLARE v_active_left INT UNSIGNED;
    DECLARE v_is_active   TINYINT;
    DECLARE v_user_id     INT UNSIGNED;
    DECLARE v_first_id    INT UNSIGNED DEFAULT NULL;
    DECLARE v_last_id     INT UNSIGNED DEFAULT NULL;

    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        RESIGNAL;
    END;

    -- Validaciones
    IF p_total IS NULL OR p_total = 0 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'p_total debe ser mayor que 0';
    END IF;
    IF p_min_age IS NULL OR p_max_age IS NULL
       OR p_min_age < 0 OR p_min_age > p_max_age OR p_max_age > 120 THEN
        SIGNAL SQLSTATE '45000'
           SET MESSAGE_TEXT = 'Rango de edad inválido (0 <= min <= max <= 120)';
    END IF;
    IF p_active_pct IS NULL OR p_active_pct < 0 OR p_active_pct > 100 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'p_active_pct debe estar entre 0 y 100';
    END IF;
    IF fn_country_is_supported(p_country) = 0 THEN
        SIGNAL SQLSTATE '45000'
           SET MESSAGE_TEXT = 'El país no tiene catálogos completos en tbc_gen_*';
    END IF;

    SET v_left        = p_total;
    SET v_active_left = ROUND(p_total * p_active_pct / 100);

    START TRANSACTION;

    WHILE v_left > 0 DO
        -- Probabilidad = activos restantes / usuarios restantes  →  total exacto
        SET v_is_active = IF(RAND() < v_active_left / v_left, 1, 0);

        CALL sp_generate_user(p_country, p_min_age, p_max_age, v_is_active, v_user_id);

        IF v_first_id IS NULL THEN SET v_first_id = v_user_id; END IF;
        SET v_last_id = v_user_id;

        IF v_is_active = 1 THEN SET v_active_left = v_active_left - 1; END IF;
        SET v_left = v_left - 1;
    END WHILE;

    INSERT INTO tb_logs (table_name, operation, db_user, description)
    VALUES ('tb_users', 'Create', LEFT(USER(), 80),
            CONCAT('Generación masiva: total=', p_total, ', país=', p_country,
                   ', edades=', p_min_age, '-', p_max_age,
                   ', activos%=', p_active_pct,
                   ', IDs ', v_first_id, ' a ', v_last_id));

    COMMIT;

    -- Resumen de verificación (asume que no hubo otras altas concurrentes en ese rango de IDs)
    SELECT p_country                                           AS pais,
           COUNT(*)                                            AS usuarios_creados,
           SUM(CAST(u.status AS UNSIGNED) = 1)                 AS activos,
           SUM(CAST(u.status AS UNSIGNED) = 0)                 AS bajas,
           ROUND(100 * SUM(CAST(u.status AS UNSIGNED) = 1) / COUNT(*), 2) AS pct_activos,
           MIN(TIMESTAMPDIFF(YEAR, p.birth_date, CURDATE()))   AS edad_min,
           MAX(TIMESTAMPDIFF(YEAR, p.birth_date, CURDATE()))   AS edad_max,
           MIN(u.ID)                                           AS primer_id,
           MAX(u.ID)                                           AS ultimo_id
      FROM tb_users u
      JOIN tb_people p ON p.user_ID = u.ID
     WHERE u.ID BETWEEN v_first_id AND v_last_id;
END ;;

CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_restore_product`(IN p_product_id INT UNSIGNED)
BEGIN
    IF NOT EXISTS (
        SELECT 1 
        FROM tb_products 
        WHERE ID = p_product_id
    ) THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'El producto especificado no existe';
    END IF;

    IF EXISTS (
        SELECT 1 
        FROM tb_products 
        WHERE ID = p_product_id 
          AND status = b'1'
    ) THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'El producto ya se encuentra activo';
    END IF;

    UPDATE tb_products 
    SET status = b'1' 
    WHERE ID = p_product_id;
END ;;

CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_soft_delete_product`(IN p_product_id INT UNSIGNED)
BEGIN
    IF NOT EXISTS (
        SELECT 1 
        FROM tb_products 
        WHERE ID = p_product_id
    ) THEN
        SIGNAL SQLSTATE '45000'
