CREATE DEFINER=`root`@`localhost` FUNCTION `fn_default_password_hash`() RETURNS char(32) CHARSET utf8mb4
    NO SQL
    DETERMINISTIC
BEGIN
    RETURN '12bce374e7be15142e8172f668da00d8';
END ;;

CREATE DEFINER=`root`@`localhost` FUNCTION `fn_gen_area_code`(p_country CHAR(2)) RETURNS char(3) CHARSET utf8mb4
    READS SQL DATA
BEGIN
    DECLARE v_total BIGINT UNSIGNED;
    DECLARE v_pick  BIGINT UNSIGNED;
    DECLARE v_area  CHAR(3);

    SELECT SUM(weight) INTO v_total
      FROM tbc_gen_phone_area_codes
     WHERE country_code = p_country AND status = b'1';
    IF v_total IS NULL THEN RETURN NULL; END IF;

    SET v_pick = FLOOR(RAND() * v_total) + 1;

    SELECT t.area_code INTO v_area
      FROM (SELECT area_code, SUM(weight) OVER (ORDER BY ID) AS cum
              FROM tbc_gen_phone_area_codes
             WHERE country_code = p_country AND status = b'1') t
     WHERE t.cum >= v_pick
     ORDER BY t.cum
     LIMIT 1;

    RETURN v_area;
END ;;

CREATE DEFINER=`root`@`localhost` FUNCTION `fn_gen_birth_date`(p_min_age INT, p_max_age INT) RETURNS date
    NO SQL
BEGIN
    DECLARE v_oldest   DATE;  -- nace hoy hace (max+1) años + 1 día  -> tiene max años
    DECLARE v_youngest DATE;  -- nace hoy hace min años              -> tiene min años

    SET v_oldest   = DATE_ADD(DATE_SUB(CURDATE(), INTERVAL (p_max_age + 1) YEAR), INTERVAL 1 DAY);
    SET v_youngest = DATE_SUB(CURDATE(), INTERVAL p_min_age YEAR);

    RETURN DATE_ADD(v_oldest,
                    INTERVAL FLOOR(RAND() * (DATEDIFF(v_youngest, v_oldest) + 1)) DAY);
END ;;

CREATE DEFINER=`root`@`localhost` FUNCTION `fn_gen_courtesy_title`(p_country CHAR(2), p_gender CHAR(1)) RETURNS varchar(30) CHARSET utf8mb4
    NO SQL
BEGIN
    DECLARE v_r DOUBLE;
    SET v_r = RAND();

    IF p_country = 'US' THEN
        IF p_gender = 'H' THEN
            RETURN IF(v_r < 0.60, 'Mr.', NULL);
        ELSEIF p_gender = 'M' THEN
            RETURN CASE WHEN v_r < 0.40 THEN 'Ms.'
                        WHEN v_r < 0.60 THEN 'Mrs.'
                        ELSE NULL END;
        END IF;
    END IF;
    RETURN NULL;   -- otros países: se agrega una rama aquí
END ;;

CREATE DEFINER=`root`@`localhost` FUNCTION `fn_gen_datetime_between`(p_from DATETIME, p_to DATETIME) RETURNS datetime
    NO SQL
BEGIN
    IF p_to <= p_from THEN RETURN p_from; END IF;
    RETURN DATE_ADD(p_from,
                    INTERVAL FLOOR(RAND() * (TIMESTAMPDIFF(SECOND, p_from, p_to) + 1)) SECOND);
END ;;

CREATE DEFINER=`root`@`localhost` FUNCTION `fn_gen_email_domain`(p_country CHAR(2)) RETURNS varchar(80) CHARSET utf8mb4
    READS SQL DATA
BEGIN
    DECLARE v_total  BIGINT UNSIGNED;
    DECLARE v_pick   BIGINT UNSIGNED;
    DECLARE v_domain VARCHAR(80);

    SELECT SUM(weight) INTO v_total
      FROM tbc_gen_email_domains
     WHERE country_code = p_country AND status = b'1';
    IF v_total IS NULL THEN RETURN NULL; END IF;

    SET v_pick = FLOOR(RAND() * v_total) + 1;

    SELECT t.domain INTO v_domain
      FROM (SELECT domain, SUM(weight) OVER (ORDER BY ID) AS cum
              FROM tbc_gen_email_domains
             WHERE country_code = p_country AND status = b'1') t
     WHERE t.cum >= v_pick
     ORDER BY t.cum
     LIMIT 1;

    RETURN v_domain;
END ;;

CREATE DEFINER=`root`@`localhost` FUNCTION `fn_gen_family_name`(p_country CHAR(2)) RETURNS varchar(60) CHARSET utf8mb4
    READS SQL DATA
BEGIN
    DECLARE v_total BIGINT UNSIGNED;
    DECLARE v_pick  BIGINT UNSIGNED;
    DECLARE v_name  VARCHAR(60);

    SELECT SUM(weight) INTO v_total
      FROM tbc_gen_family_names
     WHERE country_code = p_country AND status = b'1';
    IF v_total IS NULL THEN RETURN NULL; END IF;

    SET v_pick = FLOOR(RAND() * v_total) + 1;

    SELECT t.name INTO v_name
      FROM (SELECT name, SUM(weight) OVER (ORDER BY ID) AS cum
              FROM tbc_gen_family_names
             WHERE country_code = p_country AND status = b'1') t
     WHERE t.cum >= v_pick
     ORDER BY t.cum
     LIMIT 1;

    RETURN v_name;
END ;;

CREATE DEFINER=`root`@`localhost` FUNCTION `fn_gen_gender`() RETURNS char(1) CHARSET utf8mb4
    NO SQL
BEGIN
    RETURN IF(RAND() < 0.5, 'H', 'M');
END ;;

CREATE DEFINER=`root`@`localhost` FUNCTION `fn_gen_given_name`(p_country CHAR(2), p_gender CHAR(1), p_birth_year INT) RETURNS varchar(60) CHARSET utf8mb4
    READS SQL DATA
BEGIN
    DECLARE v_year  INT DEFAULT p_birth_year;
    DECLARE v_total BIGINT UNSIGNED;
    DECLARE v_pick  BIGINT UNSIGNED;
    DECLARE v_name  VARCHAR(60);

    SELECT SUM(weight) INTO v_total
      FROM tbc_gen_given_names
     WHERE country_code = p_country AND gender = p_gender AND status = b'1'
       AND (v_year IS NULL OR v_year BETWEEN birth_year_from AND birth_year_to);

    -- Si no hay nombres para ese año, se ignora el filtro de año
    IF v_total IS NULL THEN
        SET v_year = NULL;
        SELECT SUM(weight) INTO v_total
          FROM tbc_gen_given_names
         WHERE country_code = p_country AND gender = p_gender AND status = b'1';
    END IF;

    IF v_total IS NULL THEN RETURN NULL; END IF;

    SET v_pick = FLOOR(RAND() * v_total) + 1;

    SELECT t.name INTO v_name
      FROM (SELECT name, SUM(weight) OVER (ORDER BY ID) AS cum
              FROM tbc_gen_given_names
             WHERE country_code = p_country AND gender = p_gender AND status = b'1'
               AND (v_year IS NULL OR v_year BETWEEN birth_year_from AND birth_year_to)) t
     WHERE t.cum >= v_pick
     ORDER BY t.cum
     LIMIT 1;

    RETURN v_name;
END ;;

CREATE DEFINER=`root`@`localhost` FUNCTION `fn_gen_handle`(p_given VARCHAR(150), p_family VARCHAR(150)) RETURNS varchar(40) CHARSET utf8mb4
    NO SQL
BEGIN
    DECLARE v_first VARCHAR(60);
    DECLARE v_last  VARCHAR(60);

    SET v_first = REGEXP_REPLACE(LOWER(SUBSTRING_INDEX(COALESCE(p_given, ''), ' ', 1)), '[^a-z0-9]', '');
    SET v_last  = REGEXP_REPLACE(LOWER(COALESCE(p_family, '')), '[^a-z0-9]', '');
    IF v_first = '' THEN SET v_first = 'user'; END IF;
    IF v_last  = '' THEN SET v_last  = 'name'; END IF;

    RETURN LEFT(
        ELT(FLOOR(1 + RAND() * 7),
            CONCAT(v_first, '.', v_last),
            CONCAT(v_first, v_last),
            CONCAT(v_first, '_', v_last),
            CONCAT(LEFT(v_first, 1), v_last),
            CONCAT(v_first, v_last, LPAD(FLOOR(RAND() * 100), 2, '0')),
            CONCAT(v_first, '.', v_last, LPAD(FLOOR(RAND() * 100), 2, '0')),
            CONCAT(v_first, FLOOR(1000 + RAND() * 9000))
        ), 40);
END ;;

CREATE DEFINER=`root`@`localhost` FUNCTION `fn_gen_phone`(p_country CHAR(2)) RETURNS varchar(25) CHARSET utf8mb4
    READS SQL DATA
BEGIN
    DECLARE v_area CHAR(3);
    SET v_area = fn_gen_area_code(p_country);
    IF v_area IS NULL THEN RETURN NULL; END IF;

    IF p_country = 'US' THEN
        RETURN CONCAT('(', v_area, ') ',
                      FLOOR(2 + RAND() * 8),                 -- primer dígito 2-9
                      LPAD(FLOOR(RAND() * 100), 2, '0'), '-',
                      LPAD(FLOOR(RAND() * 10000), 4, '0'));
    END IF;

    -- Formato genérico para países sin regla propia
    RETURN CONCAT(v_area, LPAD(FLOOR(RAND() * 10000000), 7, '0'));
END ;;

CREATE DEFINER=`root`@`localhost` FUNCTION `fn_gen_unique_email`(p_given VARCHAR(150), p_family VARCHAR(150), p_country CHAR(2)) RETURNS varchar(80) CHARSET utf8mb4
    READS SQL DATA
BEGIN
    DECLARE v_try    INT DEFAULT 0;
    DECLARE v_domain VARCHAR(80);
    DECLARE v_local  VARCHAR(60);
    DECLARE v_email  VARCHAR(80);

    SET v_domain = fn_gen_email_domain(p_country);
    IF v_domain IS NULL THEN RETURN NULL; END IF;

    REPEAT
        SET v_try   = v_try + 1;
        SET v_local = fn_gen_handle(p_given, p_family);
        IF v_try > 5 THEN                       -- si hay muchas colisiones, se añade sufijo
            SET v_local = CONCAT(v_local, FLOOR(RAND() * 1000000));
        END IF;
        SET v_email = CONCAT(v_local, '@', v_domain);
    UNTIL NOT EXISTS (SELECT 1 FROM tb_users WHERE email = v_email) OR v_try >= 50
    END REPEAT;

    IF EXISTS (SELECT 1 FROM tb_users WHERE email = v_email) THEN
        SIGNAL SQLSTATE '45000'
           SET MESSAGE_TEXT = 'No fue posible generar un email único tras 50 intentos';
    END IF;
    RETURN v_email;
END ;;

CREATE DEFINER=`root`@`localhost` FUNCTION `fn_gen_unique_nick`(p_given VARCHAR(150), p_family VARCHAR(150)) RETURNS varchar(100) CHARSET utf8mb4
    READS SQL DATA
BEGIN
    DECLARE v_try  INT DEFAULT 0;
    DECLARE v_nick VARCHAR(100);

    REPEAT
        SET v_try  = v_try + 1;
        SET v_nick = fn_gen_handle(p_given, p_family);
        IF v_try > 5 THEN
            SET v_nick = CONCAT(v_nick, FLOOR(RAND() * 1000000));
        END IF;
    UNTIL NOT EXISTS (SELECT 1 FROM tb_users WHERE nickname = v_nick) OR v_try >= 50
    END REPEAT;

    IF EXISTS (SELECT 1 FROM tb_users WHERE nickname = v_nick) THEN
        SIGNAL SQLSTATE '45000'
           SET MESSAGE_TEXT = 'No fue posible generar un nick único tras 50 intentos';
    END IF;
    RETURN v_nick;
END ;;
